# ---------------------------------------------------------------------------
# Language State & Localization Helper (RU / EN)
# ---------------------------------------------------------------------------

_LANG: str = "ru"


def normalize_lang_code(raw: str | None) -> str | None:
    if raw is None:
        return None
    val = raw.strip().lower()
    if val in ("ru", "rus", "russian", "р", "ру", "рус", "русский", "1"):
        return "ru"
    if val in ("en", "eng", "english", "англ", "2"):
        return "en"
    return None


def set_lang(lang: str) -> str:
    global _LANG
    norm = normalize_lang_code(lang)
    if norm not in ("ru", "en"):
        raise ValueError(f"Unsupported language / Неподдерживаемый язык: {lang!r} (use 'ru' or 'en')")
    _LANG = norm
    return _LANG


def get_lang() -> str:
    return _LANG


def tr(ru: str, en: str) -> str:
    """Return Russian or English string depending on active language."""
    return en if _LANG == "en" else ru


def detect_early_cli_lang(argv: list[str]) -> str | None:
    """Inspect argv / CONTI_CP_LANG before building argparse so even --help is localized."""
    for i, tok in enumerate(argv):
        if tok in ("-l", "--lang") and i + 1 < len(argv):
            got = normalize_lang_code(argv[i + 1])
            if got:
                return got
        elif tok.startswith("--lang="):
            got = normalize_lang_code(tok.split("=", 1)[1])
            if got:
                return got
    env_lang = normalize_lang_code(os.environ.get("CONTI_CP_LANG"))
    return env_lang


@dataclasses.dataclass(frozen=True)
class SlotSpec:
    slot: int               # 1..12 for slave banks, 0 for gateway master key
    ecu_addr: str           # VAG diagnostic address: 17, 09, 13, 15, 47, 57, 5F, 3C, CF, 3D, A5, 8C (19 for master)
    nvm_id: int             # NvM block ID (0x60..0x6B, 0x7B for master)
    mask_bit: int | None    # Bit index 0..11 in NvM 0x5E (95640 @ 0x1329), None for master
    can_suffix: int         # KSCHUTZ / ISO-TP node suffix xx
    uds_req: str            # Physical UDS request CAN ID
    uds_resp: str           # Physical UDS response CAN ID
    off1: int               # Primary Dflash offset
    off2: int               # Mirror Dflash offset
    rec_size: int           # NvM payload size (0x42 for slots 1..11 & master, 0x40 for slot 12)
    short_ru: str           # Concise Russian module name
    short_en: str           # Concise English module name
    details_ru: str         # Hardware / ODX LL_*UDS details (RU)
    details_en: str         # Hardware / ODX LL_*UDS details (EN)
    notes_ru: str           # Specific adaptation caveats for this module (RU)
    notes_en: str           # Specific adaptation caveats for this module (EN)
    aliases: tuple[str, ...] = ()

    @property
    def short(self) -> str:
        return self.short_en if _LANG == "en" else self.short_ru

    @property
    def details(self) -> str:
        return self.details_en if _LANG == "en" else self.details_ru

    @property
    def notes(self) -> str:
        return self.notes_en if _LANG == "en" else self.notes_ru

    @property
    def cp_tx(self) -> int:
        return 0x17FC0100 | self.can_suffix if self.slot > 0 else 0

    @property
    def cp_rx(self) -> int:
        return 0x17FE0100 | self.can_suffix if self.slot > 0 else 0

    @property
    def crc_off(self) -> int:
        return 0x48 if self.rec_size == 0x42 else 0x44

    @property
    def mask_hex(self) -> str:
        return f"0x{1 << self.mask_bit:04X} (bit {self.mask_bit})" if self.mask_bit is not None else "n/a (+0x0B)"


