_SKIP_SCAN_DIRS = frozenset({".git", "__pycache__", ".venv", "venv", "env", "node_modules", ".idea", ".vscode", "public"})


def default_search_roots() -> list[Path]:
    """Return candidate dump search directories without leaking outside a standalone repo."""
    script_dir = Path(__file__).resolve().parent
    roots: list[Path] = [Path.cwd(), script_dir]
    if script_dir.name.lower() in ("tools", "scripts", "bin"):
        roots.append(script_dir.parent)
    out: list[Path] = []
    seen_r: set[Path] = set()
    for r in roots:
        try:
            rr = r.resolve()
        except OSError:
            continue
        if rr not in seen_r:
            seen_r.add(rr)
            out.append(rr)
    return out


def _collect_bin_candidates(root: Path) -> list[Path]:
    candidates = list(root.glob("*.bin"))
    sub_dirs: list[Path] = []
    for sub in ("dump_for_test", "src", "extracted", "dumps", "backup"):
        sd = root / sub
        if sd.is_dir():
            sub_dirs.append(sd)
    try:
        extra_subs = sorted(
            (
                d
                for d in root.iterdir()
                if d.is_dir() and not d.name.startswith(".") and d.name not in _SKIP_SCAN_DIRS and d not in sub_dirs
            ),
            key=lambda x: x.name.lower(),
        )[:24]
        sub_dirs.extend(extra_subs)
    except OSError:
        pass

    for sub_dir in sub_dirs:
        try:
            candidates.extend(sub_dir.glob("*.bin"))
            for sub2 in sub_dir.iterdir():
                if sub2.is_dir() and not sub2.name.startswith(".") and sub2.name not in _SKIP_SCAN_DIRS:
                    candidates.extend(sub2.glob("*.bin"))
        except OSError:
            continue
    return candidates


def discover_uflash_files(search_roots: list[Path]) -> list[Path]:
    """Find candidate 32 KB Uflash.bin files nearby."""
    uflash_list: list[Path] = []
    seen: set[Path] = set()
    for root in search_roots:
        if not root.exists() or not root.is_dir():
            continue
        candidates = _collect_bin_candidates(root)
        for p in sorted(candidates):
            try:
                rp = p.resolve()
                if rp in seen or not rp.is_file() or ".patched." in rp.name:
                    continue
                if rp.stat().st_size == UFLASH_SIZE:
                    seen.add(rp)
                    uflash_list.append(rp)
            except OSError:
                continue
    return uflash_list


# ---------------------------------------------------------------------------
# Auto-Discovery & Interactive Russian Wizard
# ---------------------------------------------------------------------------

def discover_candidate_files(search_roots: list[Path]) -> tuple[list[Path], list[Path]]:
    """Find candidate CodeFlash (1.5MB / FD_0DATA) and DataFlash (64KB) files nearby."""
    cflash_list: list[Path] = []
    dflash_list: list[Path] = []
    seen: set[Path] = set()

    for root in search_roots:
        if not root.exists() or not root.is_dir():
            continue
        candidates = _collect_bin_candidates(root)
        for p in sorted(candidates):
            try:
                rp = p.resolve()
                if rp in seen or not rp.is_file():
                    continue
                sz = rp.stat().st_size
            except OSError:
                continue
            if ".patched." in rp.name:
                continue
            if sz in (CFLASH_SIZE, APP_SIZE):
                seen.add(rp)
                cflash_list.append(rp)
            elif sz == DFLASH_SIZE:
                seen.add(rp)
                dflash_list.append(rp)
    return cflash_list, dflash_list


def prompt_line(prompt: str) -> str:
    try:
        return input(prompt)
    except (EOFError, KeyboardInterrupt):
        print(f"\n{tr('Выход.', 'Exit.')}")
        sys.exit(0)


def prompt_language_interactive(st: Style) -> str:
    """Interactive startup RU / EN language selector."""
    print()
    print(
        render_box(
            f"{AUTHOR_CREDIT} • Выбор языка / Select Language",
            [
                f"  {st.dim(f'{AUTHOR_SITE_SHORT}  •  НЕ ДЛЯ ПРОДАЖИ / NOT FOR SALE')}",
                "",
                f"  {st.cyan('[1]')} Русский  {st.green('(по умолчанию / default — Enter)')}",
                f"  {st.cyan('[2]')} English",
            ],
            st,
            "cyan",
            width=76,
        )
    )
    while True:
        ans = prompt_line("Язык / Language [1=RU, 2=EN, Enter=1]: ").strip()
        if not ans:
            return set_lang("ru")
        norm = normalize_lang_code(ans)
        if norm is not None:
            return set_lang(norm)
        print("  Введите 1 (Русский) или 2 (English) / Please enter 1 (RU) or 2 (EN).")


def prompt_startup_disclaimer(st: Style) -> bool:
    """Show prominent disclaimer right before launching wizard and confirm acceptance."""
    print()
    print(render_startup_disclaimer_box(st, width=104))
    while True:
        ans = prompt_line(
            tr(
                "\nПринимаете дисклеймер (НЕ для продажи; если что-то сломается — автор не виноват)? [Enter/д = да, 0/н = выход]: ",
                "\nAccept disclaimer (NOT for sale; if anything breaks, author is NOT at fault)? [Enter/y = yes, 0/n = exit]: ",
            )
        ).strip().lower()
        if ans in ("", "y", "yes", "д", "да", "1", "+"):
            return True
        if ans in ("0", "n", "no", "н", "нет", "q", "quit", "exit", "в", "выход", "-"):
            print(tr("Запуск отменён пользователем. Выход.", "Launch cancelled by user. Exiting."))
            return False
        print(
            tr(
                "  Нажмите Enter / 'д' для запуска или '0' / 'н' для выхода.",
                "  Press Enter / 'y' to launch or '0' / 'n' to exit.",
            )
        )


def prompt_yes_no(question: str, default: bool = True) -> bool:
    hint = tr("[Д/н]" if default else "[д/Н]", "[Y/n]" if default else "[y/N]")
    while True:
        ans = prompt_line(f"{question} {hint}: ").strip().lower()
        if not ans:
            return default
        if ans in ("y", "yes", "д", "да", "1", "+"):
            return True
        if ans in ("n", "no", "н", "нет", "0", "-"):
            return False
        print(tr("  Пожалуйста, введите 'д' (да) или 'н' (нет).", "  Please enter 'y' (yes) or 'n' (no)."))


def select_dump_file(
    kind_title: str,
    expected_desc: str,
    candidates: list[Path],
    validator,
    st: Style,
    sibling_hint_dir: Path | None = None,
) -> Path:
    """Interactive file chooser with numbered auto-detected list + Finder drag-and-drop."""
    ordered = list(candidates)
    if sibling_hint_dir is not None:
        sibling_first = [p for p in ordered if p.parent == sibling_hint_dir]
        others = [p for p in ordered if p.parent != sibling_hint_dir]
        ordered = sibling_first + others

    header_txt = tr(f"Выберите файл {kind_title}", f"Select {kind_title} file")
    print(f"\n{st.bold(header_txt)} {st.dim(f'({expected_desc})')}:")
    if ordered:
        for i, p in enumerate(ordered, 1):
            sz_kb = f"{p.stat().st_size // 1024} {tr('КБ', 'KB')}"
            tag = (
                st.green(tr(" [рядом с CodeFlash]", " [next to CodeFlash]"))
                if (sibling_hint_dir and p.parent == sibling_hint_dir)
                else ""
            )
            print(f"  {st.cyan(f'[{i}]')} {p} {st.dim(f'({sz_kb})')}{tag}")
        default_hint = tr(
            " (Enter = [1], или перетащите свой файл из Finder в окно терминала)",
            " (Enter = [1], or drag & drop your file from Finder into the terminal)",
        )
    else:
        default_hint = tr(
            " (введите путь или перетащите файл/папку из Finder в окно терминала)",
            " (enter path or drag & drop a file/folder from Finder into the terminal)",
        )

    while True:
        raw = prompt_line(f"{tr('Ваш выбор', 'Your choice')}{default_hint}: ").strip()
        if not raw and ordered:
            chosen = ordered[0]
        elif raw.isdigit() and 1 <= int(raw) <= len(ordered):
            chosen = ordered[int(raw) - 1]
        else:
            chosen = clean_user_path(raw)
            if chosen.is_dir():
                if "Uflash" in kind_title:
                    pool = discover_uflash_files([chosen])
                else:
                    c_in_dir, d_in_dir = discover_candidate_files([chosen])
                    pool = c_in_dir if "CodeFlash" in kind_title else d_in_dir
                if len(pool) == 1:
                    chosen = pool[0]
                    print(f"  {tr('Найдено в папке', 'Found in folder')}: {st.bold(str(chosen))}")
                elif len(pool) > 1:
                    ordered = pool
                    for i, p in enumerate(ordered, 1):
                        print(f"  {st.cyan(f'[{i}]')} {p}")
                    continue
                else:
                    print(
                        st.red(
                            tr(
                                f"  В папке {chosen} не найден подходящий файл ({expected_desc}).",
                                f"  No matching file ({expected_desc}) found in folder {chosen}.",
                            )
                        )
                    )
                    continue

        if not chosen.is_file():
            print(st.red(f"  {tr('Файл не найден', 'File not found')}: {chosen}"))
            continue
        try:
            data = chosen.read_bytes()
            validator(data)
            return chosen.resolve()
        except Exception as exc:
            print(st.red(f"  {tr('Ошибка проверки файла', 'File validation error')}: {exc}"))


def default_patched_path(src: Path) -> Path:
    if src.name.endswith(".patched.bin"):
        return src
    if src.suffix:
        return src.with_name(f"{src.stem}.patched{src.suffix}")
    return src.with_name(f"{src.name}.patched.bin")


def prompt_output_path(label: str, src_path: Path, st: Style) -> Path:
    suggested = default_patched_path(src_path)
    while True:
        raw = prompt_line(
            tr(
                f"Куда сохранить {st.bold(label)} [Enter = {st.green(str(suggested))}]: ",
                f"Output path for {st.bold(label)} [Enter = {st.green(str(suggested))}]: ",
            )
        ).strip()
        out = suggested if not raw else clean_user_path(raw)
        if out.resolve() == src_path.resolve():
            print(
                st.yellow(
                    tr(
                        "  Внимание: выбран путь ПОВЕРХ исходного файла! Рекомендуется сохранять в *.patched.bin,"
                        " чтобы оригинал остался нетронутым.",
                        "  Warning: you selected the ORIGINAL input file! Saving to *.patched.bin is strongly"
                        " recommended so your backup stays untouched.",
                    )
                )
            )
            if not prompt_yes_no(
                tr("  Точно перезаписать исходный файл?", "  Overwrite the original file anyway?"),
                default=False,
            ):
                continue
        return out


def wizard_bind_flow(cflash_candidates: list[Path], dflash_candidates: list[Path], st: Style) -> None:
    print()
    print(
        render_box(
            tr(
                "ПОШАГОВЫЙ МАСТЕР ПРИВЯЗКИ БЛОКОВ CP (ШАГ 1 ИЗ 5 — ПАМЯТКА ПЕРЕД НАЧАЛОМ)",
                "STEP-BY-STEP CP BINDING WIZARD (STEP 1 OF 5 — BEFORE YOU START)",
            ),
            [
                tr(
                    f"1. У вас должны быть вычитаны дампы {st.bold('РОДНОГО')} гейтвея автомобиля (3Q0 907 530 xx):",
                    f"1. Make sure you read the dumps from your car's {st.bold('ORIGINAL')} gateway (3Q0 907 530 xx):",
                ),
                tr(
                    "   • CodeFlash.bin / Cflash.bin (1.5 МБ = 1 572 864 Б)  и  DataFlash.bin / Dflash.bin (64 КБ = 65 536 Б).",
                    "   • CodeFlash.bin / Cflash.bin (1.5 MB = 1,572,864 B)  and  DataFlash.bin / Dflash.bin (64 KB = 65,536 B).",
                ),
                tr(
                    "   • Uflash.bin (32 КБ) сохраните у себя в резервной копии — патчить и перезаписывать его НЕ нужно!",
                    "   • Keep Uflash.bin (32 KB) in your safe backup — DO NOT patch or overwrite it!",
                ),
                tr(
                    f"2. Также подготовьте {st.bold('16-байтный рабочий ключ CP (IKA / 00 BE)')} каждого привязываемого блока",
                    f"2. Have ready the {st.bold('16-byte active CP key (IKA / 00 BE)')} of each slave ECU you want to bind",
                ),
                tr(
                    "   (32 hex-символа, вычитанные из привязываемого ЭБУ; НЕ путайте с нулевым групповым ключом GFA!).",
                    "   (32 hex characters read from the target ECU; DO NOT confuse with the all-zero GFA group key!).",
                ),
            ],
            st,
            "cyan",
            width=104,
        )
    )

    # Step 2: Select CodeFlash + DataFlash and inspect
    print(
        f"\n{st.cyan(tr('━━ ШАГ 2 ИЗ 5: Выбор и проверка дампов родного гейтвея ━━', '━━ STEP 2 OF 5: Select & Inspect Gateway Dumps ━━'))}"
    )
    cflash_path = select_dump_file(
        tr("CodeFlash (прошивка шлюза)", "CodeFlash (gateway firmware)"),
        tr("1 572 864 Б Cflash.bin или 1 523 200 Б FD_0DATA", "1,572,864 B Cflash.bin or 1,523,200 B FD_0DATA"),
        cflash_candidates,
        split_cflash_or_app,
        st,
    )
    dflash_path = select_dump_file(
        tr("DataFlash (энергонезависимая память ключей CP)", "DataFlash (CP keys non-volatile memory)"),
        tr("65 536 Б Dflash.bin / DataFlash.bin", "65,536 B Dflash.bin / DataFlash.bin"),
        dflash_candidates,
        validate_dflash_bytes,
        st,
        sibling_hint_dir=cflash_path.parent,
    )

    cf_raw = cflash_path.read_bytes()
    df_raw = dflash_path.read_bytes()
    cf_info = analyze_cflash(cf_raw)
    df_states = analyze_dflash(df_raw)
    state_by_slot = {s.spec.slot: s for s in df_states}

    print()
    print(format_cflash_report(str(cflash_path), cf_info, st))
    print()
    print(format_dflash_table(str(dflash_path), df_raw, df_states, st))

    ignore_crc = False
    if not cf_info.crc_ok:
        print(
            st.red(
                tr(
                    "\nВНИМАНИЕ: Входной файл CodeFlash имеет неверную контрольную сумму CRC-16 на 0x0000C21C! "
                    "Возможно, дамп был вычитан с ошибкой или изменён вручную.",
                    "\nWARNING: Input CodeFlash has an invalid Application CRC-16 at 0x0000C21C! "
                    "The dump may be a bad read or manually edited.",
                )
            )
        )
        if not prompt_yes_no(
            tr("Продолжить несмотря на несовпадение входного CRC-16?", "Continue despite input CRC-16 mismatch?"),
            default=False,
        ):
            return
        ignore_crc = True

    if cf_info.hook_vaddr is None:
        print(
            st.red(
                tr(
                    "\nОШИБКА: В этом файле CodeFlash не найдена сигнатура KSCHUTZ callback! Патч невозможен.",
                    "\nERROR: KSCHUTZ callback signature not found in this CodeFlash! Cannot patch.",
                )
            )
        )
        return

    # Step 3: Choose target CP bank(s)
    print(
        f"\n{st.cyan(tr('━━ ШАГ 3 ИЗ 5: Выбор банка(ов) CP (какой блок привязываем к гейтвею) ━━', '━━ STEP 3 OF 5: Choose Target CP Bank(s) / VAG ECU(s) ━━'))}"
    )
    print(
        tr(
            "  Можно указать ОДИН или НЕСКОЛЬКО банков через запятую/пробел — по номеру банка (1..12)\n"
            "  или по диагностическому адресу блока VAG:",
            "  Enter ONE or MULTIPLE banks separated by commas/spaces — by bank number (1..12)\n"
            "  or by VAG diagnostic ECU address:",
        )
    )
    for row_slice in (SLAVE_SLOTS[:4], SLAVE_SLOTS[4:8], SLAVE_SLOTS[8:12]):
        print(
            "    "
            + "  |  ".join(
                f"{st.bold(f'{s.slot}')}={st.cyan(s.ecu_addr)} ({s.short.split('(')[0].strip()})"
                for s in row_slice
            )
        )
    print(
        st.dim(
            tr(
                "  Примеры ввода:  47   или   13   или   5F   или   A5   или   3C, CF   или   5, 7",
                "  Examples:       47   or    13   or    5F   or    A5   or    3C, CF   or    5, 7",
            )
        )
    )

    selected_specs: list[SlotSpec] = []
    while not selected_specs:
        raw_sel = prompt_line(
            tr(
                "\nВведите номер банка (1..12) или адрес блока VAG: ",
                "\nEnter bank number (1..12) or VAG ECU address: ",
            )
        ).strip()
        try:
            selected_specs = parse_slot_list(raw_sel, allow_master=False)
        except ValueError as exc:
            print(st.red(f"  {exc}"))
            continue

        # Friendly disambiguation hint if literal '9' was entered
        raw_tokens = [t.strip() for t in re.split(r"[,;\s]+", raw_sel) if t.strip()]
        if "9" in raw_tokens:
            print(
                st.yellow(
                    tr(
                        "  Обратите внимание: цифра '9' — это Банк 9 (блок CF Side Assist 2). "
                        "Если вам нужен блок бортовой сети 09 (BCM) — это Банк 2 (введите '09' или '2').",
                        "  Note: single digit '9' selects Bank 9 (ECU CF Side Assist 2). "
                        "If you meant Central Electrics 09 (BCM), that is Bank 2 (enter '09' or '2').",
                    )
                )
            )
            if not prompt_yes_no(
                tr("  Оставить выбранным Банк 9 (CF Side Assist 2)?", "  Keep Bank 9 (CF Side Assist 2) selected?"),
                default=True,
            ):
                selected_specs = []
                continue

    print(tr("\nВыбраны банки для записи:", "\nSelected banks to program:"))
    any_previously_empty = False
    for sp in selected_specs:
        st_slot = state_by_slot[sp.slot]
        if st_slot.empty:
            any_previously_empty = True
            cur_txt = st.yellow(
                tr("сейчас ПУСТ (FF..FF) — дооснащение новым блоком", "currently EMPTY (FF..FF) — retrofitting new ECU")
            )
        elif st_slot.kind == "SHE":
            cur_txt = st.green(
                tr(
                    "сейчас АКТИВЕН (заводской шифроконтейнер SHE — замена штатного блока)",
                    "currently ACTIVE (factory encrypted SHE — replacing existing ECU)",
                )
            )
        else:
            cur_txt = st.cyan(
                tr(f"сейчас ОТКРЫТЫЙ КЛЮЧ ({st_slot.first16_hex})", f"currently PLAINTEXT IKA ({st_slot.first16_hex})")
            )
        print(
            tr(
                f"  • {st.bold(f'Банк {sp.slot:2d}')} [{st.cyan(f'ЭБУ {sp.ecu_addr}')}] — {st.bold(sp.short)}: {cur_txt}",
                f"  • {st.bold(f'Bank {sp.slot:2d}')} [{st.cyan(f'ECU {sp.ecu_addr}')}] — {st.bold(sp.short)}: {cur_txt}",
            )
        )
        print(f"    {st.dim(sp.notes)}")

    # Decide on 95640 mask bypass automatically with explanation
    if any_previously_empty:
        print()
        print(
            render_box(
                tr(
                    "Обнаружена запись в ранее ПУСТОЙ банк — обход маски внешней 95640 EEPROM",
                    "Writing to a Previously EMPTY Bank — External 95640 EEPROM Mask Bypass",
                ),
                [
                    tr(
                        "Хотя бы один из выбранных банков сейчас пуст (FF..FF). На заводе его бит в 12-битной маске",
                        "At least one selected bank is currently empty (FF..FF). Its bit in the 12-bit learned-bank",
                    ),
                    tr(
                        "обученных блоков во внешней микросхеме SPI EEPROM 95640 (NvM 0x5E @ 0x1329) равен 0.",
                        "bitmask inside external SPI EEPROM 95640 (NvM 0x5E @ 0x1329) is 0 from the factory.",
                    ),
                    tr(
                        "Чтобы НЕ выпаивать и НЕ править 95640 (она защищена AES-CMAC), рекомендуется включить",
                        "To avoid desoldering or editing 95640 (which is AES-CMAC protected), enabling the 2-byte",
                    ),
                    tr(
                        "2-байтовый обход проверки маски в CodeFlash (82 3d -> 00 00).",
                        "mask check bypass in CodeFlash (82 3d -> 00 00) is strongly recommended.",
                    ),
                ],
                st,
                "yellow",
                width=104,
            )
        )
        bypass_mask = prompt_yes_no(
            tr(
                "Включить обход проверки маски 95640 в CodeFlash (рекомендуется)?",
                "Enable 95640 EEPROM mask check bypass in CodeFlash (recommended)?",
            ),
            default=True,
        )
    elif cf_info.mask_bypassed:
        print(
            st.green(
                tr(
                    "\n  В исходном CodeFlash уже включён обход маски 95640 — сохраняем его.",
                    "\n  Input CodeFlash already has 95640 mask bypass enabled — keeping it.",
                )
            )
        )
        bypass_mask = True
    else:
        print(
            st.dim(
                tr(
                    "\n  Все выбранные банки уже были активны в родном DataFlash (бит в 95640 EEPROM уже взведён с завода).",
                    "\n  All selected banks were already active in DataFlash (their bit in 95640 EEPROM is already set).",
                )
            )
        )
        bypass_mask = prompt_yes_no(
            tr(
                "Включить также обход маски 95640 (обычно НЕ нужно при замене уже стоявшего блока)?",
                "Also enable 95640 mask bypass (usually NOT needed when replacing an existing factory ECU)?",
            ),
            default=False,
        )

    # Step 4: Enter 16-byte plaintext CP key(s)
    print(
        f"\n{st.cyan(tr('━━ ШАГ 4 ИЗ 5: Ввод 16-байтного открытого ключа CP (IKA / 00 BE) ━━', '━━ STEP 4 OF 5: Enter 16-Byte Plaintext CP Key (IKA / 00 BE) ━━'))}"
    )
    print(
        render_box(
            tr("Где брать 16-байтный ключ (краткая шпаргалка)", "Where to Get the 16-Byte Key (Quick Cheat Sheet)"),
            [
                tr(
                    "• Нужен 16-байтный (32 hex-символа) рабочий ключ IKA (Key ID 00 BE) из самого привязываемого блока.",
                    "• Enter the 16-byte (32 hex chars) working key IKA (Key ID 00 BE) read from the target ECU.",
                ),
                tr(
                    "• НЕ вводите нули 00..00 из группового ключа GFA (00 BD) нового блока и НЕ вводите 0000..00E5 из M1!",
                    "• DO NOT enter zeros 00..00 from Virgin group key GFA (00 BD) and DO NOT enter 0000..00E5 from M1!",
                ),
                tr(
                    "• Формат ввода любой: слитно (32 символа), через пробелы или двоеточия (например: A1 B2 C3 ...).",
                    "• Any hex format works: continuous 32 hex chars, spaces, or colons (e.g. A1 B2 C3 ...).",
                ),
                tr(
                    "• Если вы сами задаёте новый ключ с нуля (для стенда/эмулятора и блока одновременно) — введите 'gen'.",
                    "• Type 'gen' to generate a fresh random 16-byte key (if writing the same key to both ECU & gateway).",
                ),
                tr(
                    "• Запись нулей 00..00 только в гейтвей НЕ обойдёт CP: ответ 80 02 проверяет САМ ведомый ЭБУ на своём IKA!",
                    "• Writing 00..00 in the gateway alone NEVER bypasses CP: the slave ECU itself verifies 80 02 with its IKA!",
                ),
                tr(
                    "• Банк 0 шлюза (Master 0xDA00 / GFA) трогать НЕ нужно: его порча уронит в CP сразу все 12 блоков авто.",
                    "• Leave Gateway Bank 0 (Master 0xDA00 / GFA) untouched: corrupting it drops all 12 car ECUs into CP.",
                ),
            ],
            st,
            "blue",
            width=104,
        )
    )

    updates: list[tuple[SlotSpec, bytes]] = []
    for sp in selected_specs:
        while True:
            raw_k = prompt_line(
                tr(
                    f"\nКлюч IKA (16 байт / 32 hex, либо 'gen') для {st.bold(f'Банка {sp.slot} — ЭБУ {sp.ecu_addr} ({sp.short})')}: ",
                    f"\nIKA Key (16 bytes / 32 hex, or 'gen') for {st.bold(f'Bank {sp.slot} — ECU {sp.ecu_addr} ({sp.short})')}: ",
                )
            ).strip()
            if raw_k.lower() in ("gen", "random", "rnd"):
                key_bytes = os.urandom(16)
                print(
                    f"  {tr('Сгенерирован случайный 16-байтный ключ', 'Generated random 16-byte key')}: "
                    f"{st.cyan(key_bytes.hex())}"
                )
                print(
                    st.yellow(
                        tr(
                            "  Обязательно запишите этот же ключ в слот IKA самого привязываемого блока/эмулятора!",
                            "  Make sure to write this exact same key into the IKA slot of the slave ECU / emulator!",
                        )
                    )
                )
            else:
                try:
                    key_bytes = parse_hex_key(raw_k)
                except ValueError as exc:
                    print(st.red(f"  {exc}"))
                    continue

            warns = check_key_warnings(key_bytes)
            rejected = False
            for sev, msg in warns:
                color = st.red if sev == "STOP" else st.yellow
                print(color(f"  [{sev}] {msg}"))
                if not prompt_yes_no(
                    tr("  Всё равно использовать этот ключ?", "  Use this key anyway?"),
                    default=False,
                ):
                    rejected = True
                    break
            if rejected:
                continue

            updates.append((sp, key_bytes))
            break

    # Step 5: Choose output paths, apply, self-verify, and print flashing checklist
    print(
        f"\n{st.cyan(tr('━━ ШАГ 5 ИЗ 5: Сохранение готовых файлов и автоматическая верификация ━━', '━━ STEP 5 OF 5: Save Patched Dumps & Self-Verify ━━'))}"
    )
    out_cflash = prompt_output_path(tr("пропатченный CodeFlash", "patched CodeFlash"), cflash_path, st)
    out_dflash = prompt_output_path(tr("обновлённый DataFlash", "updated DataFlash"), dflash_path, st)

    patched_cf, cf_desc, new_crc16 = apply_cflash_patch(
        cf_raw,
        mode="hybrid",
        bypass_eeprom_mask=bypass_mask,
        preserve_existing_mask_bypass=cf_info.mask_bypassed,
        ignore_input_crc=ignore_crc,
    )
    patched_df, written_slots = write_dflash_slots(df_raw, updates)

    out_cflash.parent.mkdir(parents=True, exist_ok=True)
    out_dflash.parent.mkdir(parents=True, exist_ok=True)
    out_cflash.write_bytes(patched_cf)
    out_dflash.write_bytes(patched_df)

    # Re-read from disk and verify everything!
    verify_cf = analyze_cflash(out_cflash.read_bytes())
    verify_df = analyze_dflash(out_dflash.read_bytes())
    verify_ok = (
        verify_cf.fbl_ok
        and verify_cf.crc_ok
        and verify_cf.hook_mode == "HYBRID"
        and all(s.crc_ok and s.mirrored for s in verify_df if not s.empty)
    )

    summary_lines = [
        f"{tr('CodeFlash сохранён', 'CodeFlash saved   ')} : {st.green(str(out_cflash))}",
        f"  • {tr('Режим патча   ', 'Patch mode    ')} : {cf_desc}",
        f"  • App CRC-16     : 0x{new_crc16:04X} @ 0x0000C21C [{'OK' if verify_cf.crc_ok else 'ERR'}]",
        f"{tr('DataFlash сохранён', 'DataFlash saved   ')} : {st.green(str(out_dflash))}",
    ]
    for (sp, crc32_val), (_, key_b) in zip(written_slots, updates):
        summary_lines.append(
            f"  • {tr('Банк', 'Bank')} {sp.slot:2d} ({tr('ЭБУ', 'ECU')} {sp.ecu_addr}, 0x{sp.off1:04X}/0x{sp.off2:04X}) : "
            f"IKA={st.cyan(key_b.hex())}  CRC-32=0x{crc32_val:08X} [OK]"
        )
    summary_lines.append(
        f"{tr('Самопроверка с диска', 'Disk self-check    ')}: "
        + (
            st.green(
                tr(
                    "УСПЕШНО — все контрольные суммы, зеркала банков и заводские SHE-слоты целы!",
                    "PASSED — all checksums, bank mirrors, and untouched factory SHE slots are intact!",
                )
            )
            if verify_ok
            else st.red(tr("ОШИБКА САМОПРОВЕРКИ!", "SELF-VERIFICATION FAILED!"))
        )
    )
    print()
    print(
        render_box(
            tr("ГОТОВО! Файлы успешно созданы и проверены", "DONE! Patched Files Created & Verified"),
            summary_lines,
            st,
            "green",
            width=104,
        )
    )

    next_steps = [
        tr(
            f"1. Запишите в гейтвей {st.bold(out_cflash.name)} (1.5 МБ) и {st.bold(out_dflash.name)} (64 КБ).",
            f"1. Flash {st.bold(out_cflash.name)} (1.5 MB) and {st.bold(out_dflash.name)} (64 KB) back to the gateway.",
        ),
        tr(
            "   Родной Uflash.bin (32 КБ) и паспорт 0x00000000..0x0000C1FF уже сохранены нетронутыми!",
            "   Original Uflash.bin (32 KB) and identity block 0x00000000..0x0000C1FF remain untouched!",
        ),
        tr(
            "2. Установите гейтвей в машину (или подайте на столе +12V KL30, GND KL31 и обязательно +12V KL15 Зажигание).",
            "2. Reinstall in the car (or on a bench harness apply +12V KL30, GND KL31, AND +12V KL15 Ignition).",
        ),
        tr(
            "3. Для проверки обмена CP в шине CAN (500 кбит/с, Extended 29-bit) смотрите кадры:",
            "3. To verify the CP handshake on 29-bit Extended CAN (500 kbps), watch:",
        ),
    ]
    for sp, _ in updates:
        next_steps.append(
            tr(
                f"   • Банк {sp.slot:2d} (ЭБУ {sp.ecu_addr} — {sp.short}): "
                f"запрос 19->ЭБУ {st.bold(f'0x{sp.cp_tx:08X}')}, ответ ЭБУ->19 {st.bold(f'0x{sp.cp_rx:08X}')} "
                f"(80 01 -> C0 01 -> 80 02 -> C0 02)",
                f"   • Bank {sp.slot:2d} (ECU {sp.ecu_addr} — {sp.short}): "
                f"19->ECU req {st.bold(f'0x{sp.cp_tx:08X}')}, ECU->19 resp {st.bold(f'0x{sp.cp_rx:08X}')} "
                f"(80 01 -> C0 01 -> 80 02 -> C0 02)",
            )
        )
    next_steps.append(
        tr(
            "4. Подключите диагностику (ODIS / VCDS / OBDeleven) и сотрите ошибки в блоке 19 и привязанном ЭБУ.",
            "4. Connect diagnostics (ODIS / VCDS / OBDeleven) and clear DTCs in Gateway 19 and the bound ECU.",
        )
    )
    print()
    print(
        render_box(
            tr("ЧТО ДЕЛАТЬ ДАЛЬШЕ (пошаговая проверка)", "NEXT STEPS (Verification Checklist)"),
            next_steps,
            st,
            "blue",
            width=104,
        )
    )


def wizard_engineering_flow(
    cflash_candidates: list[Path],
    uflash_candidates: list[Path],
    st: Style,
) -> None:
    print()
    print(
        render_box(
            tr(
                "ПРЕВРАЩЕНИЕ ГЕЙТВЕЯ В «ИНЖЕНЕРНЫЙ ЮНИТ» (ЧТО ЭТО ДАЁТ И ПРАВДА ПРО ФЛАГ 0xC21E)",
                "CONVERT GATEWAY TO AN 'ENGINEERING UNIT' (WHAT IT ENABLES & THE TRUTH ABOUT 0xC21E)",
            ),
            [
                tr(
                    f"• {st.yellow('Важно про 0x0000C21E')}: по адресу 0xC21E лежит НЕ инженерный флаг, а счётчик диапазонов CRC-16 (=1)!",
                    f"• {st.yellow('Truth about 0x0000C21E')}: 0xC21E is NOT an engineering flag — it is the CRC-16 range count (=1)!",
                ),
                tr(
                    "  Зануление 0xC21E=0 НЕ отключает RSA и ЛОМАЕТ прошивку по UDS (0x01000DA6 валит 31 01 FF 01 с NOK).",
                    "  Zeroing 0xC21E=0 NEVER skips RSA and BREAKS UDS flashing (0x01000DA6 rejects 31 01 FF 01 with NOK).",
                ),
                tr(
                    "  (Прямой Sample/Dev флаг в бутлодере есть на гейтвее Lear MPC5748G, а на Continental механизмы другие:)",
                    "  (A literal FBL Sample/Dev flag exists on Lear MPC5748G; Continental RH850 uses the gates below:)",
                ),
                "",
                tr(
                    f"1. {st.bold('Инженерный RSA-Free бутлодер в Uflash.bin')} (@ 0x0100342A: e2 57 14 eb -> 00 ea 00 00):",
                    f"1. {st.bold('Engineering RSA-Free Bootloader in Uflash.bin')} (@ 0x0100342A: e2 57 14 eb -> 00 ea 00 00):",
                ),
                tr(
                    "   Загрузчик принимает ЛЮБЫЕ кастомные .odx/.frf по OBD UDS (ODIS-E / VCP) без проверки подписи RSA-1024!",
                    "   FBL CheckMemory (31 01 02 02) accepts ANY custom .odx/.frf over OBD UDS without RSA-1024 verification!",
                ),
                tr(
                    "   (В .odx обязательно оставьте любую 128-байтную заглушку <FW-SIGNATURE> @ 0x01002E70 и валидный CRC-16 @ 0xC21C.)",
                    "   (Keep any 128-byte <FW-SIGNATURE> placeholder in .odx @ 0x01002E70 and valid App CRC-16 @ 0xC21C.)",
                ),
                tr(
                    "   Uflash.bin (32 КБ) не имеет собственного CRC/BOOT_MAC и никогда не затирается при обновлении по OBD.",
                    "   Uflash.bin (32 KB) has no self-CRC/BOOT_MAC and is never overwritten during OBD updates.",
                ),
                tr(
                    f"2. {st.bold('Инженерные протоколы в CodeFlash.bin')} (Feature 0x80/0x81/0x83 + 0x0000A167 + 0x07FC80FE):",
                    f"2. {st.bold('Application Engineering Protocols in CodeFlash.bin')} (Feature 0x80/0x81/0x83 + 0x0000A167 + 0x07FC80FE):",
                ),
                tr(
                    "   • Открывает живой калибровочный протокол ASAM CCP v2.1 (CAN 0x1BFC8600 RX / 0x1BFC8601 TX, Station 0x0055):",
                    "   • Unlocks live ASAM CCP v2.1 calibration protocol (CAN 0x1BFC8600 RX / 0x1BFC8601 TX, Station 0x0055):",
                ),
                tr(
                    "     прямое чтение Cflash / Dflash / Uflash / RAM и живая запись в RAM по CAN без пайки 95640 EEPROM!",
                    "     live read of Cflash / Dflash / Uflash / RAM and live write to RAM over CAN without touching 95640!",
                ),
                tr(
                    "   • Открывает заводской вход Continental CAN RAM-Loader (0x07FC80FE -> 0x6F0/0x6F1, запуск кода в RAM).",
                    "   • Unlocks Continental factory CAN RAM-Loader entry (0x07FC80FE -> 0x6F0/0x6F1, arbitrary code in RAM).",
                ),
            ],
            st,
            "cyan",
            width=104,
        )
    )

    print(
        f"  {st.cyan('[1]')} "
        + tr(
            f"Полный инженерный комплект: пропатчить {st.bold('И CodeFlash.bin, И Uflash.bin')} {st.green('(рекомендуется)')}",
            f"Full Engineering Bundle: patch {st.bold('BOTH CodeFlash.bin AND Uflash.bin')} {st.green('(recommended)')}",
        )
    )
    print(
        f"  {st.cyan('[2]')} "
        + tr(
            "Пропатчить ТОЛЬКО Uflash.bin (RSA-Free бутлодер: прошивка любых .odx по OBD UDS без RSA)",
            "Patch ONLY Uflash.bin (RSA-Free bootloader: flash any .odx over OBD UDS without RSA)",
        )
    )
    print(
        f"  {st.cyan('[3]')} "
        + tr(
            "Пропатчить ТОЛЬКО CodeFlash.bin (ASAM CCP v2.1 чтение/запись памяти по CAN + 0x07FC80FE RAM-Loader)",
            "Patch ONLY CodeFlash.bin (ASAM CCP v2.1 live CAN memory R/W + 0x07FC80FE RAM-Loader)",
        )
    )
    print(
        f"  {st.cyan('[4]')} "
        + tr(
            "Вернуть заводскую серийную защиту (откат инженерного патча в CodeFlash.bin и/или Uflash.bin)",
            "Restore factory production locks (revert engineering patch in CodeFlash.bin and/or Uflash.bin)",
        )
    )
    print(f"  {st.cyan('[0]')} {tr('Назад в главное меню', 'Back to main menu')}")

    sub = prompt_line(tr("\nВыберите режим [0-4, Enter=1]: ", "\nChoose mode [0-4, Enter=1]: ")).strip() or "1"
    if sub == "0":
        return
    if sub not in ("1", "2", "3", "4"):
        print(st.yellow(tr("  Неверный выбор.", "  Invalid selection.")))
        return

    restore = sub == "4"
    do_cf = sub in ("1", "3")
    do_uf = sub in ("1", "2")
    if restore:
        do_cf = prompt_yes_no(
            tr("Восстановить серийную защиту в CodeFlash.bin?", "Restore production locks in CodeFlash.bin?"),
            default=True,
        )
        do_uf = prompt_yes_no(
            tr("Восстановить штатную проверку RSA в Uflash.bin?", "Restore stock RSA check in Uflash.bin?"),
            default=True,
        )
        if not do_cf and not do_uf:
            return

    cf_dir: Path | None = None
    summary_lines: list[str] = []

    if do_cf:
        cf_path = select_dump_file(
            "CodeFlash",
            tr("1 572 864 Б Cflash.bin или 1 523 200 Б FD_0DATA", "1,572,864 B Cflash.bin or 1,523,200 B FD_0DATA"),
            cflash_candidates,
            split_cflash_or_app,
            st,
        )
        cf_dir = cf_path.parent
        cf_raw = cf_path.read_bytes()
        cf_info = analyze_cflash(cf_raw)
        print()
        print(format_cflash_report(str(cf_path), cf_info, st))

        ignore_crc = restore
        if not restore and not cf_info.crc_ok and cf_info.crc_range_count != 0:
            if not prompt_yes_no(
                tr("Входной CRC-16 не совпадает. Всё равно продолжить?", "Input CRC-16 mismatch. Continue anyway?"),
                default=False,
            ):
                return
            ignore_crc = True

        out_cf = prompt_output_path(
            tr("инженерный CodeFlash", "engineering CodeFlash")
            if not restore
            else tr("серийный CodeFlash", "production CodeFlash"),
            cf_path,
            st,
        )
        patched_cf, cf_desc, new_crc = apply_engineering_patch(
            cf_raw,
            restore_stock=restore,
            ignore_input_crc=ignore_crc,
        )
        out_cf.parent.mkdir(parents=True, exist_ok=True)
        out_cf.write_bytes(patched_cf)
        ver_cf = analyze_cflash(out_cf.read_bytes())
        summary_lines.append(f"CodeFlash : {st.green(str(out_cf))}")
        summary_lines.append(f"  • {cf_desc}")
        summary_lines.append(f"  • App CRC-16 @ 0x0000C21C = 0x{new_crc:04X} [{'OK' if ver_cf.crc_ok else 'ERR'}]")

    if do_uf:
        uf_path = select_dump_file(
            "Uflash",
            tr("32 768 Б Uflash.bin (загрузчик FBL @ 0x01000000)", "32,768 B Uflash.bin (FBL @ 0x01000000)"),
            uflash_candidates,
            validate_uflash_bytes,
            st,
            sibling_hint_dir=cf_dir,
        )
        uf_raw = uf_path.read_bytes()
        uf_info = analyze_uflash(uf_raw)
        print()
        print(format_uflash_report(str(uf_path), uf_info, st))

        out_uf = prompt_output_path(
            tr("инженерный RSA-Free Uflash", "engineering RSA-Free Uflash")
            if not restore
            else tr("стоковый Uflash", "stock Uflash"),
            uf_path,
            st,
        )
        patched_uf, uf_desc = apply_uflash_rsa_patch(uf_raw, restore_stock=restore)
        out_uf.parent.mkdir(parents=True, exist_ok=True)
        out_uf.write_bytes(patched_uf)
        ver_uf = analyze_uflash(out_uf.read_bytes())
        ok_flag = (ver_uf.rsa_bypassed if not restore else (not ver_uf.rsa_bypassed)) and ver_uf.signature_found
        summary_lines.append(f"Uflash    : {st.green(str(out_uf))}")
        summary_lines.append(f"  • {uf_desc} [{'OK' if ok_flag else 'ERR'}]")

    print()
    print(
        render_box(
            tr("ГОТОВО! Инженерный патч выполнен и проверен", "DONE! Engineering Patch Applied & Verified"),
            summary_lines,
            st,
            "green",
            width=104,
        )
    )


def wizard_rsa_flow(
    cflash_candidates: list[Path],
    dflash_candidates: list[Path],
    st: Style,
) -> None:
    print()
    print(
        render_box(
            tr(
                "ЗАМЕНА ПУБЛИЧНОГО КЛЮЧА RSA-1024 (e = 3) И ПОДПИСЬ SWaP FSC / ПРОШИВОК ODX",
                "RSA-1024 (e = 3) PUBLIC KEY REPLACEMENT & SWaP FSC / FBL ODX SIGNING",
            ),
            [
                tr(
                    f"• {st.bold('Зачем заменять RSA-1024 на свою ключевую пару')}:",
                    f"• {st.bold('Why replace RSA-1024 with your own keypair')}:",
                ),
                tr(
                    "  1) SWaP / FeC (FSAG): выпускать и заливать по OBD (2E 3C 01 -> 31 01 C0 01) свои 171-байтные FSC v2",
                    "  1) SWaP / FeC (FSAG): generate & install over OBD (2E 3C 01 -> 31 01 C0 01) custom 171-byte FSC v2 files",
                ),
                tr(
                    "     на ЛЮБЫЕ коды FeC (например 10000100 Выбор профиля движения FPA / Driving Mode, 10000300 MKE и др.)!",
                    "     for ANY FeC (e.g. 10000100 Driving Profile Selection FPA, 10000300 MKE Fatigue Detection, etc.)!",
                ),
                tr(
                    "  2) Бутлодер FBL (Sector 5 @ 0x0000A2F7): подписывать свои кастомные .odx без патча Uflash.bin!",
                    "  2) FBL Bootloader (Sector 5 @ 0x0000A2F7): sign custom .odx updates while keeping stock Uflash.bin!",
                ),
                "",
                tr(
                    f"• {st.yellow('ГЛАВНАЯ НАХОДКА — хватит ли простой замены в CodeFlash.bin?')}",
                    f"• {st.yellow('KEY FINDING — is replacing RSA in CodeFlash.bin alone enough?')}",
                ),
                tr(
                    "  НЕТ для SWaP! На инициализированном шлюзе (Dflash[0xDC11]==1) функция старта 0x0007B7CA",
                    "  NO for SWaP! On an initialized gateway (Dflash[0xDC11]==1), boot routine 0x0007B7CA",
                ),
                tr(
                    "  НЕ копирует ключ из CodeFlash, а проверка FSC (31 01 C0 01) берёт кэшированный модуль из",
                    "  SKIPS copying from CodeFlash, and FSC verification (31 01 C0 01) reads the cached modulus from",
                ),
                tr(
                    f"  {st.bold('DataFlash.bin NvM 0x7C @ 0xDB04..0xDB83')}! Поэтому мастер синхронно обновляет И CodeFlash (+CRC-16),",
                    f"  {st.bold('DataFlash.bin NvM 0x7C @ 0xDB04..0xDB83')}! That is why this wizard updates BOTH CodeFlash (+CRC-16)",
                ),
                tr(
                    "  И DataFlash (+CRC-32 @ 0xDCE4), сохраняя родной VCRN и все заводские лицензии SWaP (0xDD00..0xE780)!",
                    "  AND DataFlash (+CRC-32 @ 0xDCE4), preserving hardware VCRN and all factory EOL SWaP slots!",
                ),
            ],
            st,
            "cyan",
            width=104,
        )
    )

    print(
        f"  {st.cyan('[1]')} "
        + tr(
            f"Под ключ: сгенерировать (или загрузить) пару RSA-1024 + заменить ключ в {st.bold('CodeFlash + DataFlash')}",
            f"Turnkey: generate (or load) RSA-1024 keypair + replace key in {st.bold('CodeFlash + DataFlash')}",
        )
    )
    print(
        f"  {st.cyan('[2]')} "
        + tr(
            "Только сгенерировать новую пару ключей RSA-1024 (e = 3) -> сохранить .json + .private.pem + .public.pem",
            "Generate a new RSA-1024 (e = 3) keypair only -> save .json + .private.pem + .public.pem",
        )
    )
    print(
        f"  {st.cyan('[3]')} "
        + tr(
            "Подписать сертификат активации SWaP FSC v2 (171 байт / 0xAB, RIPEMD-160 + RSA-1024) для 2E 3C 01 -> 31 01 C0 01",
            "Sign a VAG SWaP FSC v2 activation certificate (171 B / 0xAB, RIPEMD-160 + RSA-1024) for 2E 3C 01 -> 31 01 C0 01",
        )
    )
    print(
        f"  {st.cyan('[4]')} "
        + tr(
            "Подписать прошивку CodeFlash / FD_0DATA для ODX (<FW-SIGNATURE>, SHA-1 + RSA-1024)",
            "Sign CodeFlash / FD_0DATA firmware for ODX (<FW-SIGNATURE>, SHA-1 + RSA-1024)",
        )
    )
    print(f"  {st.cyan('[0]')} {tr('Назад в главное меню', 'Back to main menu')}")

    sub = prompt_line(tr("\nВыберите действие [0-4, Enter=1]: ", "\nChoose action [0-4, Enter=1]: ")).strip() or "1"
    if sub == "0":
        return

    if sub == "2":
        default_kp = Path.cwd() / "conti_j533_rsa1024_keypair.json"
        raw_out = prompt_line(
            tr(
                f"Куда сохранить ключевую пару JSON/PEM [Enter = {st.green(str(default_kp))}]: ",
                f"Output path for JSON/PEM keypair [Enter = {st.green(str(default_kp))}]: ",
            )
        ).strip()
        kp_path = default_kp if not raw_out else clean_user_path(raw_out)
        print(tr("  Генерация криптостойких 512-битных простых p, q (e=3)…", "  Generating 512-bit primes p, q (e=3)…"))
        kp = generate_rsa1024_e3_keypair()
        j_p, priv_p, pub_p = save_rsa1024_keypair_bundle(kp_path, kp)
        print(
            render_box(
                tr("ПАРА КЛЮЧЕЙ RSA-1024 (e = 3) СГЕНЕРИРОВАНА", "RSA-1024 (e = 3) KEYPAIR GENERATED"),
                [
                    f"JSON (n, e, d, p, q) : {st.green(str(j_p))}",
                    f"Private PEM (OpenSSL): {st.green(str(priv_p))}",
                    f"Public PEM  (OpenSSL): {st.green(str(pub_p))}",
                    f"Modulus N (128 B)    : {st.cyan(kp['n_hex'][:32] + '…' + kp['n_hex'][-16:])}",
                ],
                st,
                "green",
                width=104,
            )
        )
        return

    if sub == "1":
        use_new = prompt_yes_no(
            tr(
                "Сгенерировать новую пару ключей RSA-1024 (e = 3) сейчас? (Нет = указать существующий .json/.pem/hex)",
                "Generate a fresh RSA-1024 (e = 3) keypair now? (No = load existing .json/.pem/hex)",
            ),
            default=True,
        )
        priv_d: int | None = None
        key_saved_note = ""
        if use_new:
            default_kp = Path.cwd() / "conti_j533_rsa1024_keypair.json"
            raw_out = prompt_line(
                tr(
                    f"Куда сохранить приватный ключ JSON/PEM [Enter = {st.green(str(default_kp))}]: ",
                    f"Where to save your private key JSON/PEM [Enter = {st.green(str(default_kp))}]: ",
                )
            ).strip()
            kp_path = default_kp if not raw_out else clean_user_path(raw_out)
            print(tr("  Генерация пары ключей RSA-1024 (e = 3)…", "  Generating RSA-1024 (e = 3) keypair…"))
            kp = generate_rsa1024_e3_keypair()
            j_p, priv_p, _ = save_rsa1024_keypair_bundle(kp_path, kp)
            mod_bytes = bytes.fromhex(kp["n_hex"])
            priv_d = int(kp["d_hex"], 16)
            key_saved_note = f"{j_p} (+ {priv_p.name})"
        else:
            while True:
                raw_k = prompt_line(
                    tr(
                        "Путь к .json / .pem / 128B .bin или 256 hex-символов модуля N: ",
                        "Path to .json / .pem / 128B .bin or 256-hex modulus N: ",
                    )
                ).strip()
                try:
                    mod_bytes, priv_d = load_rsa1024_key_material(raw_k)
                    break
                except Exception as exc:
                    print(st.red(f"  {exc}"))

        cf_path = select_dump_file(
            "CodeFlash",
            tr("1 572 864 Б Cflash.bin или 1 523 200 Б FD_0DATA", "1,572,864 B Cflash.bin or 1,523,200 B FD_0DATA"),
            cflash_candidates,
            split_cflash_or_app,
            st,
        )
        df_path = select_dump_file(
            "DataFlash",
            tr("65 536 Б Dflash.bin / DataFlash.bin", "65,536 B Dflash.bin / DataFlash.bin"),
            dflash_candidates,
            validate_dflash_bytes,
            st,
            sibling_hint_dir=cf_path.parent,
        )
        cf_raw = cf_path.read_bytes()
        df_raw = df_path.read_bytes()
        cf_info = analyze_cflash(cf_raw)

        also_fbl = False
        if cf_info.has_prefix:
            also_fbl = prompt_yes_no(
                tr(
                    "Заменить также публичный ключ бутлодера FBL в Sector 5 (0x0000A2F7) для подписи своих .odx?",
                    "Also replace FBL bootloader public key in Sector 5 (0x0000A2F7) for signing custom .odx files?",
                ),
                default=True,
            )

        out_cf = prompt_output_path(tr("CodeFlash со своим RSA", "CodeFlash with custom RSA"), cf_path, st)
        out_df = prompt_output_path(tr("DataFlash со своим кэшем SWaP RSA", "DataFlash with custom SWaP RSA"), df_path, st)

        patched_cf, cf_notes, new_crc16 = apply_cflash_rsa_modulus(
            cf_raw,
            mod_bytes,
            patch_swap=True,
            patch_fbl=also_fbl,
            ignore_input_crc=not cf_info.crc_ok,
        )
        patched_df, df_crc32, vcrn_5b = apply_dflash_swap_rsa_modulus(df_raw, mod_bytes)

        out_cf.parent.mkdir(parents=True, exist_ok=True)
        out_df.parent.mkdir(parents=True, exist_ok=True)
        out_cf.write_bytes(patched_cf)
        out_df.write_bytes(patched_df)

        ver_cf = analyze_cflash(out_cf.read_bytes())
        ver_sw = analyze_dflash_swap(out_df.read_bytes())
        lines = []
        if key_saved_note:
            lines.append(f"{tr('Ключевая пара ', 'Keypair saved ')} : {st.green(key_saved_note)}")
        lines.append(f"CodeFlash      : {st.green(str(out_cf))}  (CRC-16 = 0x{new_crc16:04X} [{'OK' if ver_cf.crc_ok else 'ERR'}])")
        for n_str in cf_notes:
            lines.append(f"  • {n_str}")
        lines.append(f"DataFlash      : {st.green(str(out_df))}")
        if ver_sw.magic_ok:
            lines.append(
                f"  • NvM 0x7C @ 0xDB00: CRC-32 = 0x{df_crc32:08X} [{'OK' if ver_sw.crc_ok else 'ERR'}], "
                f"VCRN = {st.cyan(vcrn_5b.hex().upper())}, "
                f"{tr('сохранено заводских FeC', 'preserved factory FeCs')}: {len(ver_sw.active_fscs)}"
            )
        else:
            lines.append(
                tr(
                    "  • NvM 0x7C ещё не инициализирован (Virgin) — ключ скопируется из CodeFlash автоматически при первом старте!",
                    "  • NvM 0x7C is uninitialized (Virgin) — gateway will copy the new key from CodeFlash on first boot!",
                )
            )
        print()
        print(
            render_box(
                tr("ГОТОВО! Публичный ключ RSA-1024 успешно заменён", "DONE! RSA-1024 Public Key Replaced"),
                lines,
                st,
                "green",
                width=104,
            )
        )

        if priv_d is not None and ver_sw.magic_ok and prompt_yes_no(
            tr(
                "\nСразу выпустить подписанный сертификат SWaP FSC (например 10000100 FPA Driving Profile) под этот гейтвей?",
                "\nGenerate a signed SWaP FSC certificate right now (e.g. 10000100 FPA Driving Profile) for this gateway?",
            ),
            default=False,
        ):
            if ver_sw.inactive_fecs:
                inact_hint = ", ".join(f"{fc:08X}" for fc in ver_sw.inactive_fecs)
                print(
                    st.dim(
                        tr(
                            f"  Подсказка: неактивные FeC в вашем Dflash: {inact_hint}",
                            f"  Hint: supported inactive FeCs in your Dflash: {inact_hint}",
                        )
                    )
                )
            raw_fec = prompt_line(
                tr(
                    "Код FeC (8 hex-символов, Enter = 10000100 Выбор профиля движения FPA): ",
                    "FeC code (8 hex chars, Enter = 10000100 Driving Profile Selection FPA): ",
                )
            ).strip() or "10000100"
            fec_int = int(re.sub(r"^0x", "", raw_fec, flags=re.IGNORECASE), 16)
            vin_def = ver_sw.vin
            raw_vin = prompt_line(
                tr(
                    f"VIN автомобиля (17 символов, Enter = '{vin_def or 'без привязки к VIN'}'): ",
                    f"Vehicle VIN (17 chars, Enter = '{vin_def or 'wildcard'}'): ",
                )
            ).strip() or vin_def
            ts_val = max(int(time.time()), ver_sw.slot_timestamps.get(fec_int, 0) + 1)
            fsc_bytes = build_signed_fsc(
                fec_int, vcrn_5b, raw_vin, mod_bytes, priv_d, timestamp_unix=ts_val
            )
            fsc_out = out_df.with_name(f"FSC_{fec_int:08X}_{vcrn_5b.hex().upper()}.fsc")
            fsc_out.write_bytes(fsc_bytes)
            print(
                render_box(
                    tr("СЕРТИФИКАТ SWaP FSC v2 (171 Б / 0xAB) ПОДПИСАН", "SWaP FSC v2 CERTIFICATE (171 B / 0xAB) SIGNED"),
                    [
                        f"{tr('Файл FSC (171 Б)', 'FSC File (171 B)')} : {st.green(str(fsc_out))}",
                        f"FeC / VCRN / VIN : {st.bold(f'0x{fec_int:08X}')}  /  {st.cyan(vcrn_5b.hex().upper())}  /  {raw_vin or 'WILDCARD'}",
                        f"1) UDS Session   : 10 40   {st.dim(tr('(сессия EOL 0x40; 10 03 отклоняется!)', '(VW EOL session 0x40; 10 03 is rejected!)'))}",
                        f"2) SecurityAccess: 27 03 -> 27 04 <key>   {st.dim(tr('(код доступа 20103)', '(login 20103)'))}",
                        f"3) WDBI 0x3C01   : 2E 3C 01 {fsc_bytes.hex().upper()}",
                        f"4) CheckSWaP     : 31 01 C0 01   ->   31 03 C0 01 {st.dim(tr('(опрос результата)', '(poll result)'))}",
                    ],
                    st,
                    "green",
                    width=104,
                )
            )
        return

    if sub == "3":
        while True:
            raw_k = prompt_line(
                tr(
                    "Путь к приватному ключу RSA-1024 (.json или .private.pem): ",
                    "Path to RSA-1024 private key (.json or .private.pem): ",
                )
            ).strip()
            try:
                mod_bytes, priv_d = load_rsa1024_key_material(raw_k)
                if priv_d is None:
                    raise ValueError(
                        tr(
                            "В указанном файле нет приватной экспоненты d! Укажите .json или .private.pem.",
                            "No private exponent d in that file! Provide .json or .private.pem.",
                        )
                    )
                break
            except Exception as exc:
                print(st.red(f"  {exc}"))

        vcrn_def = ""
        vin_def = ""
        slot_ts_map: dict[int, int] = {}
        if dflash_candidates and prompt_yes_no(
            tr(
                "Прочитать VCRN и VIN автоматически из файла DataFlash.bin?",
                "Read VCRN and VIN automatically from DataFlash.bin?",
            ),
            default=True,
        ):
            df_path = select_dump_file(
                "DataFlash",
                tr("65 536 Б Dflash.bin / DataFlash.bin", "65,536 B Dflash.bin / DataFlash.bin"),
                dflash_candidates,
                validate_dflash_bytes,
                st,
            )
            sw = analyze_dflash_swap(df_path.read_bytes())
            if sw.magic_ok and len(sw.vcrn) == 5:
                vcrn_def = sw.vcrn.hex().upper()
                vin_def = sw.vin
                slot_ts_map = dict(sw.slot_timestamps)
                if sw.inactive_fecs:
                    inact_hint = ", ".join(f"{fc:08X}" for fc in sw.inactive_fecs)
                    print(
                        st.dim(
                            tr(
                                f"  Доступные неактивные FeC в этом Dflash: {inact_hint}",
                                f"  Supported inactive FeCs in this Dflash: {inact_hint}",
                            )
                        )
                    )

        raw_fec = prompt_line(
            tr(
                "Код FeC в hex (Enter = 10000100 Выбор профиля движения FPA): ",
                "FeC code in hex (Enter = 10000100 Driving Profile Selection FPA): ",
            )
        ).strip() or "10000100"
        fec_int = int(re.sub(r"^0x", "", raw_fec, flags=re.IGNORECASE), 16)

        while True:
            raw_vcrn = prompt_line(
                tr(
                    f"5-байтный VCRN шлюза (10 hex{f', Enter = {vcrn_def}' if vcrn_def else ''}): ",
                    f"Gateway 5-byte VCRN (10 hex{f', Enter = {vcrn_def}' if vcrn_def else ''}): ",
                )
            ).strip() or vcrn_def
            v_clean = re.sub(r"[\s:\-]+", "", raw_vcrn)
            if len(v_clean) == 10 and re.fullmatch(r"[0-9a-fA-F]{10}", v_clean):
                vcrn_5b = bytes.fromhex(v_clean)
                break
            print(st.red(tr("  Введите ровно 10 hex-символов (5 байт VCRN из DID 0x3C03).", "  Enter 10 hex chars (5-byte VCRN from DID 0x3C03).")))

        raw_vin = prompt_line(
            tr(
                f"17-символьный VIN автомобиля (Enter = '{vin_def or 'без привязки к VIN'}'): ",
                f"17-character vehicle VIN (Enter = '{vin_def or 'wildcard'}'): ",
            )
        ).strip() or vin_def

        ts_val = max(int(time.time()), slot_ts_map.get(fec_int, 0) + 1)
        fsc_bytes = build_signed_fsc(
            fec_int, vcrn_5b, raw_vin, mod_bytes, priv_d, timestamp_unix=ts_val
        )
        fsc_out = Path.cwd() / f"FSC_{fec_int:08X}_{vcrn_5b.hex().upper()}.fsc"
        fsc_out.write_bytes(fsc_bytes)
        print(
            render_box(
                tr("СЕРТИФИКАТ SWaP FSC v2 (171 Б / 0xAB) УСПЕШНО СОЗДАН", "SWaP FSC v2 CERTIFICATE (171 B / 0xAB) CREATED"),
                [
                    f"{tr('Файл FSC (171 Б)', 'FSC File (171 B)')} : {st.green(str(fsc_out))}",
                    f"{tr('HEX (342 симв.) ', 'HEX (342 chars) ')} : {fsc_bytes.hex().upper()}",
                    f"1) UDS Session   : 10 40   {st.dim(tr('(строго EOL 0x40; 10 03 отклоняется @ 0x0001F03C!)', '(VW EOL 0x40 required; 10 03 rejected @ 0x0001F03C!)'))}",
                    f"2) SecurityAccess: 27 03 -> 27 04 <key>   {st.dim(tr('(логин 20103)', '(login 20103)'))}",
                    f"3) WDBI 0x3C01   : 2E 3C 01 {fsc_bytes.hex().upper()}",
                    f"4) CheckSWaP     : 31 01 C0 01   ->   31 03 C0 01 {st.dim(tr('(4 байта запуск, затем опрос)', '(4-byte start, then poll)'))}",
                ],
                st,
                "green",
                width=104,
            )
        )
        return

    if sub == "4":
        while True:
            raw_k = prompt_line(
                tr(
                    "Путь к приватному ключу RSA-1024 (.json или .private.pem): ",
                    "Path to RSA-1024 private key (.json or .private.pem): ",
                )
            ).strip()
            try:
                mod_bytes, priv_d = load_rsa1024_key_material(raw_k)
                if priv_d is None:
                    raise ValueError(tr("Нужен файл с приватным ключом d (.json или .private.pem).", "Private key d required (.json or .private.pem)."))
                break
            except Exception as exc:
                print(st.red(f"  {exc}"))

        cf_path = select_dump_file(
            "CodeFlash",
            tr("1 572 864 Б Cflash.bin или 1 523 200 Б FD_0DATA", "1,572,864 B Cflash.bin or 1,523,200 B FD_0DATA"),
            cflash_candidates,
            split_cflash_or_app,
            st,
        )
        sig_bytes = sign_fbl_odx_application(cf_path.read_bytes(), mod_bytes, priv_d)
        sig_out = cf_path.with_name(f"{cf_path.stem}.odx_signature.bin")
        sig_out.write_bytes(sig_bytes)
        print(
            render_box(
                tr("ПОДПИСЬ ПРОШИВКИ ДЛЯ ODX (<FW-SIGNATURE>) ГОТОВА", "ODX FIRMWARE SIGNATURE (<FW-SIGNATURE>) READY"),
                [
                    f"{tr('Бинарный файл (128 Б)', 'Binary File (128 B)  ')} : {st.green(str(sig_out))}",
                    f"<FW-SIGNATURE> HEX    : {sig_bytes.hex().upper()}",
                ],
                st,
                "green",
                width=104,
            )
        )


def wizard_inspect_flow(
    cflash_candidates: list[Path],
    dflash_candidates: list[Path],
    uflash_candidates: list[Path],
    st: Style,
) -> None:
    print(
        f"\n{st.cyan(tr('━━ ИНСПЕКЦИЯ ДАМПОВ ГЕЙТВЕЯ CONTINENTAL J533 ━━', '━━ CONTINENTAL J533 GATEWAY DUMP INSPECTION ━━'))}"
    )
    want_cf = prompt_yes_no(
        tr(
            "Проверить файл прошивки CodeFlash.bin / Cflash.bin?",
            "Inspect CodeFlash.bin / Cflash.bin firmware dump?",
        ),
        default=True,
    )
    cf_dir: Path | None = None
